const clock = new THREE.Clock();

// Cinematic renderer configuration
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Light, airy background per policy — cosmic nursery atmosphere
scene.background = new THREE.Color(0xeef2f5);
scene.fog = new THREE.FogExp2(0xeef2f5, 0.035);

// Cinematic three-point lighting with stellar key light
const keyLight = new THREE.DirectionalLight(0xfff0e0, 2.0);
keyLight.position.set(5, 8, 6);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.1;
keyLight.shadow.camera.far = 40;
keyLight.shadow.camera.left = -10;
keyLight.shadow.camera.right = 10;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xddeeff, 0.7);
fillLight.position.set(-6, 2, 4);

const rimLight = new THREE.PointLight(0xffaaee, 0.8, 25);
rimLight.position.set(-3, 4, -5);

const ambientLight = new THREE.AmbientLight(0x405060, 0.4);

// Central protostar illumination (intensifies during birth)
const stellarLight = new THREE.PointLight(0xffaa55, 0, 20);
stellarLight.position.set(0, 0, 0);

scene.add(ambientLight, keyLight, fillLight, rimLight, stellarLight);

// Star formation system container
const nebulaSystem = new THREE.Group();
scene.add(nebulaSystem);

// 1. Protostar core — detailed sphere with physical glow
const coreGeo = new THREE.SphereGeometry(0.6, 32, 32);
const coreMat = new THREE.MeshPhysicalMaterial({
  color: 0xff6600,
  emissive: 0xff2200,
  emissiveIntensity: 0.2,
  metalness: 0.1,
  roughness: 0.3,
  clearcoat: 0.8,
  clearcoatRoughness: 0.1,
  transmission: 0.15,
  thickness: 1.5,
  transparent: true,
  opacity: 0.95
});
const protostar = new THREE.Mesh(coreGeo, coreMat);
protostar.castShadow = true;
nebulaSystem.add(protostar);

// 2. Accretion disk — layered geometry with PBR materials
const diskGroup = new THREE.Group();
nebulaSystem.add(diskGroup);

// Inner hot disk
const innerDiskGeo = new THREE.RingGeometry(0.8, 1.6, 64, 2);
const innerDiskMat = new THREE.MeshStandardMaterial({
  color: 0xffaa44,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.9,
  metalness: 0.7,
  roughness: 0.3,
  emissive: 0xff4400,
  emissiveIntensity: 0.2
});
const innerDisk = new THREE.Mesh(innerDiskGeo, innerDiskMat);
innerDisk.rotation.x = Math.PI / 2;
diskGroup.add(innerDisk);

// Outer cool disk
const outerDiskGeo = new THREE.RingGeometry(1.6, 3.0, 64, 4);
const outerDiskMat = new THREE.MeshStandardMaterial({
  color: 0x88aabb,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.6,
  metalness: 0.4,
  roughness: 0.6
});
const outerDisk = new THREE.Mesh(outerDiskGeo, outerDiskMat);
outerDisk.rotation.x = Math.PI / 2;
outerDisk.position.y = -0.05;
diskGroup.add(outerDisk);

// 3. Bipolar outflow jets (stellar birth signature)
const jetGeo = new THREE.CylinderGeometry(0.1, 0.4, 6, 16, 8, true);
const jetMat = new THREE.MeshBasicMaterial({
  color: 0xaaddff,
  transparent: true,
  opacity: 0.4,
  side: THREE.DoubleSide,
  blending: THREE.AdditiveBlending,
  depthWrite: false
});

const topJet = new THREE.Mesh(jetGeo, jetMat);
topJet.position.y = 3.5;
nebulaSystem.add(topJet);

const bottomJet = new THREE.Mesh(jetGeo, jetMat);
bottomJet.position.y = -3.5;
bottomJet.rotation.z = Math.PI;
nebulaSystem.add(bottomJet);

// 4. Molecular cloud particles (collapsing gas and dust)
const particleCount = 1500;
const cloudGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const velocities = new Float32Array(particleCount * 3);
const originalDist = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  // Spherical distribution
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 4 + Math.random() * 6;

  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta) * 0.4; // Flattened cloud
  positions[i * 3 + 2] = r * Math.cos(phi);

  originalDist[i] = r;

  // Inward spiral velocity
  velocities[i * 3] = -positions[i * 3] * 0.02;
  velocities[i * 3 + 1] = (Math.random() - 0.5) * 0.02;
  velocities[i * 3 + 2] = -positions[i * 3 + 2] * 0.02;
}

cloudGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const cloudMat = new THREE.PointsMaterial({
  color: 0x6688aa,
  size: 0.08,
  transparent: true,
  opacity: 0.7,
  sizeAttenuation: true,
  blending: THREE.NormalBlending
});
const cloud = new THREE.Points(cloudGeo, cloudMat);
nebulaSystem.add(cloud);

// 5. Nebula halo — subtle volumetric feel
const haloGeo = new THREE.IcosahedronGeometry(5, 2);
const haloMat = new THREE.MeshPhysicalMaterial({
  color: 0xcceeff,
  transparent: true,
  opacity: 0.12,
  transmission: 0.4,
  roughness: 0.2,
  side: THREE.BackSide,
  depthWrite: false
});
const halo = new THREE.Mesh(haloGeo, haloMat);
nebulaSystem.add(halo);

// 6. Spark particles (accretion events)
const sparkCount = 100;
const sparkGeo = new THREE.BufferGeometry();
const sparkPos = new Float32Array(sparkCount * 3);
const sparkLife = new Float32Array(sparkCount);
for (let i = 0; i < sparkCount; i++) {
  sparkPos[i * 3] = 0;
  sparkPos[i * 3 + 1] = 0;
  sparkPos[i * 3 + 2] = 0;
  sparkLife[i] = Math.random();
}
sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3));
const sparkMat = new THREE.PointsMaterial({
  color: 0xffffaa,
  size: 0.12,
  transparent: true,
  opacity: 0.8,
  blending: THREE.AdditiveBlending,
  sizeAttenuation: true
});
const sparks = new THREE.Points(sparkGeo, sparkMat);
nebulaSystem.add(sparks);

// Camera and controls setup
camera.position.set(7, 4, 8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);
controls.minDistance = 3;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI / 2 + 0.2;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.5;

// Birth animation sequence variables
const birthDuration = 20; // seconds for full ignition
let birthPhase = 0;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  // Birth phase calculation (0 to 1 over birthDuration)
  birthPhase = Math.min(t / birthDuration, 1);

  // Protostar ignition — brightening and heating up
  const ignitionCurve = Math.pow(birthPhase, 2);
  coreMat.emissiveIntensity = 0.2 + ignitionCurve * 3.0;
  coreMat.color.setHSL(0.08 - ignitionCurve * 0.03, 1.0, 0.5 + ignitionCurve * 0.3);
  protostar.scale.setScalar(1 + ignitionCurve * 0.2 + Math.sin(t * 3) * 0.02);

  // Stellar light intensifies
  stellarLight.intensity = ignitionCurve * 5;
  stellarLight.color.setHSL(0.1 - ignitionCurve * 0.05, 1, 0.5);

  // Accretion disk rotation with differential velocity
  innerDisk.rotation.z = t * 0.5;
  outerDisk.rotation.z = t * 0.25;

  // Disk wobble (precession)
  diskGroup.rotation.x = Math.PI / 2 + Math.sin(t * 0.2) * 0.05;
  diskGroup.rotation.z = Math.cos(t * 0.15) * 0.03;

  // Bipolar jets pulsing
  const jetPulse = 0.5 + 0.5 * Math.sin(t * 2) * (0.5 + ignitionCurve * 0.5);
  topJet.scale.setScalar(jetPulse);
  bottomJet.scale.setScalar(jetPulse);
  topJet.material.opacity = 0.3 * jetPulse;
  bottomJet.material.opacity = 0.3 * jetPulse;
  topJet.rotation.y = t * 0.5;
  bottomJet.rotation.y = t * 0.5;

  // Molecular cloud collapse — particles spiral inward
  const posAttr = cloud.geometry.attributes.position;
  for (let i = 0; i < particleCount; i++) {
    const ix = i * 3;
    const iy = i * 3 + 1;
    const iz = i * 3 + 2;

    let x = posAttr.array[ix];
    let y = posAttr.array[iy];
    let z = posAttr.array[iz];

    // Spiral motion toward center
    const dist = Math.sqrt(x*x + z*z);
    const angle = Math.atan2(z, x);
    const spiralSpeed = 0.5 + ignitionCurve * 2.0;
    const newAngle = angle + delta * spiralSpeed;
    const collapseSpeed = 0.5 + ignitionCurve * 1.5;
    const newDist = Math.max(0.9, dist - delta * collapseSpeed * (1 + 2/dist));

    posAttr.array[ix] = newDist * Math.cos(newAngle);
    posAttr.array[iz] = newDist * Math.sin(newAngle);
    posAttr.array[iy] = y * (1 - delta * 0.5); // Flatten toward disk plane

    // Reset particles that get too close (accreted) to maintain flow
    if (newDist < 1.0 && Math.random() < 0.1) {
      const theta = Math.random() * Math.PI * 2;
      const r = 8 + Math.random() * 4;
      posAttr.array[ix] = r * Math.cos(theta);
      posAttr.array[iz] = r * Math.sin(theta);
      posAttr.array[iy] = (Math.random() - 0.5) * 2;
    }
  }
  posAttr.needsUpdate = true;
  cloud.rotation.y = t * 0.05;

  // Spark animation (accretion flashes)
  const sparkPos = sparks.geometry.attributes.position;
  for (let i = 0; i < sparkCount; i++) {
    sparkLife[i] -= delta * (1 + ignitionCurve * 2);
    if (sparkLife[i] <= 0) {
      // Respawn near disk
      const angle = Math.random() * Math.PI * 2;
      const r = 0.8 + Math.random() * 0.4;
      sparkPos.array[i * 3] = r * Math.cos(angle);
      sparkPos.array[i * 3 + 1] = (Math.random() - 0.5) * 0.2;
      sparkPos.array[i * 3 + 2] = r * Math.sin(angle);
      sparkLife[i] = 1;
    } else {
      // Move outward
      sparkPos.array[i * 3] *= 1 + delta * 2;
      sparkPos.array[i * 3 + 1] *= 1 + delta * 2;
      sparkPos.array[i * 3 + 2] *= 1 + delta * 2;
    }
  }
  sparkPos.needsUpdate = true;
  sparks.material.opacity = 0.8 * (0.5 + 0.5 * Math.sin(t * 10));

  // Nebula halo breathing
  halo.scale.setScalar(1 + Math.sin(t * 0.3) * 0.05);
  halo.rotation.y = t * 0.02;
  halo.rotation.z = t * 0.01;

  // Rim light intensity modulation
  rimLight.intensity = 0.8 + Math.sin(t * 0.7) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}

animate();

